fields.InputDefinition:
{
  "goal": "Open the Chat application via the app switcher and wait for the workspace. In the left sidebar there is a 'Search conversations...' input at the top of the conversation list. Type a few characters into it. Confirm the conversation list RESPONDS: the visible conversations narrow to those matching your text, OR a clear empty/no-match state is shown if nothing matches. Then clear the box and confirm the full list returns. The list reacting to your input is success regardless of how many conversations exist. Pages can take 10-30s to load in this resource-constrained environment — wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}
